   MInstruction *LHS = Cmp->getOperand<0>();
   MInstruction *RHS = Cmp->getOperand<1>();
+  // Comparing two reads of the same FP local is a NaN/ordered test, not
+  // a constant: x != x is true for NaN, and x == x is false for NaN.
+  // Restrict this to direct reads so no load, call, or trapping expression
+  // is discarded or evaluated fewer times.
+  const auto *LRead = llvm::dyn_cast<DreadInstruction>(LHS);
+  const auto *RRead = llvm::dyn_cast<DreadInstruction>(RHS);
+  if (LRead && RRead && LRead->getVarIdx() == RRead->getVarIdx() &&
+      LHS->getType() == RHS->getType() &&
+      (LHS->getType()->isF32() || LHS->getType()->isF64())) {
+    if (Cmp->getPredicate() == CmpInstruction::FCMP_UNE) {
+      return makeICmp(CmpInstruction::FCMP_UNO, Cmp->getType(), LHS, LHS);
+    }
+    if (Cmp->getPredicate() == CmpInstruction::FCMP_OEQ) {
+      return makeICmp(CmpInstruction::FCMP_ORD, Cmp->getType(), LHS, LHS);
+    }
+  }
   if (LHS == RHS && LHS->getType()->isInteger() && isPureExpr(LHS)) {
